std::string displayNumber(double n){char value[64];std::snprintf(value,sizeof value,"%.6g",n);return value;}
const std::array<const char*,9> contexts={"block","gui","ground","fixed","head","thirdperson_righthand","thirdperson_lefthand","firstperson_righthand","firstperson_lefthand"};
const std::array<const char*,7> layers={"auto","solid","cutout","cutout_mipped","cutout_mipped_all","translucent","tripwire"};
const std::array<const char*,4> arrangements={"single","grid","glass_layers","corner"};
Image decodePreview(const std::string& encoded){
    auto bytes=unbase64(encoded);HGLOBAL memory=GlobalAlloc(GMEM_MOVEABLE,bytes.size());if(!memory)throw std::runtime_error("Preview allocation failed");
    auto data=GlobalLock(memory);std::memcpy(data,bytes.data(),bytes.size());GlobalUnlock(memory);IStream* stream=nullptr;
    if(CreateStreamOnHGlobal(memory,TRUE,&stream)!=S_OK){GlobalFree(memory);throw std::runtime_error("Preview stream failed");}
    Image result;{Gdiplus::Bitmap bitmap(stream);if(bitmap.GetLastStatus()==Gdiplus::Ok&&bitmap.GetWidth()<=4096&&bitmap.GetHeight()<=4096){result=Image(int(bitmap.GetWidth()),int(bitmap.GetHeight()));Gdiplus::Rect r(0,0,result.w,result.h);Gdiplus::BitmapData locked{};if(bitmap.LockBits(&r,Gdiplus::ImageLockModeRead,PixelFormat32bppARGB,&locked)==Gdiplus::Ok){for(int y=0;y<result.h;++y)for(int x=0;x<result.w;++x){auto p=static_cast<uint8_t*>(locked.Scan0)+y*locked.Stride+x*4;result.set(x,y,{p[2],p[1],p[0],p[3]});}bitmap.UnlockBits(&locked);}}}stream->Release();if(!result.w)throw std::runtime_error("Preview PNG decoding failed");return result;
}
