    J base=J::object(),resources=J::array(),report,observed;bool done=false,busy=false,loading=false,dirty=false,dragging=false;
    uint64_t serial=0;int page=0,mouseX=0,mouseY=0,batchOffset=0,nextOffset=-1;std::wstring message=L"选择工程资源，刷新后查看实际模型。";
