    void touch(){if(loading)return;dirty=true;++serial;busy=false;nextOffset=-1;say(L"参数已修改 · 点击刷新预览");}
    void load(const J& value){
        if(!value.null()&&!value.isObject())throw std::runtime_error("预览选项须为对象");
        for(auto key:{"subject","state","camera","environment","biome_tint","block_tints","item_tints"})if(!value[key].null()&&!value[key].isObject())throw std::runtime_error(std::string(key)+" 须为对象");
        for(auto key:{"mipmap_levels","mip_level"}){int lower=std::string(key)=="mip_level"?-1:0;if(value.contains(key)&&(!value[key].isNumber()||value[key].integer()<lower||value[key].integer()>4))throw std::runtime_error("无效的 mipmap 级别");}
        auto validChoice=[](const J& v,const auto& choices){return v.isString()&&std::any_of(choices.begin(),choices.end(),[&](auto name){return v.str()==name;});};
        if(value["subject"].contains("kind")&&!validChoice(value["subject"]["kind"],std::array<const char*,4>{"document","model","blockstate","texture"}))throw std::runtime_error("无效资源类型");
        if(value["subject"].contains("id")&&!value["subject"]["id"].isString())throw std::runtime_error("资源标识须为文本");
        if(value.contains("context")&&!validChoice(value["context"],contexts))throw std::runtime_error("无效显示场景");
        if(value.contains("render_type")&&!validChoice(value["render_type"],layers))throw std::runtime_error("无效渲染层");
        if(value.contains("arrangement")&&!validChoice(value["arrangement"],arrangements))throw std::runtime_error("无效场景排列");
        if(!value["emission_sources"].null()&&!value["emission_sources"].isArray())throw std::runtime_error("emission_sources 须为数组");
        if(value["emission_sources"].size()&&!value["emission_sources"][0].isObject())throw std::runtime_error("光源须为对象");
        scene.reset();loading=true;for(auto& p:pages)p->loading=true;base=value.null()?J::object():value;
        auto select=[&](const char* id,const auto& names,std::string value){int index=0;for(int i=0;i<int(names.size());++i)if(value==names[i])index=i;comboSet(fields[id],index);};
        auto subject=base["subject"];comboSet(fields["kind"],subject["kind"].str()=="model"?1:subject["kind"].str()=="blockstate"?2:subject["kind"].str()=="texture"?3:0);setText(fields["resource"],subject["id"].str("current"));
        select("context",contexts,base["context"].str("block"));select("layer",layers,base["render_type"].str("auto"));select("arrangement",arrangements,base["arrangement"].str("single"));
        setText(fields["state"],base["state"].isObject()?base["state"].dump():"{}");comboSet(fields["mips"],base["mipmap_levels"].integer(4));comboSet(fields["lod"],base["mip_level"].integer(-1)+1);
        setText(fields["distance"],displayNumber(base["camera"]["distance"].number(64)));setText(fields["time"],displayNumber(base["time_ms"].number()));comboSet(fields["sort"],base["sort_translucent"].boolean(true)?1:0);
        setText(fields["sky"],std::to_string(base["environment"]["sky_light"].integer(15)));setText(fields["block"],std::to_string(base["environment"]["block_light"].integer()));setText(fields["gamma"],displayNumber(base["environment"]["gamma"].number()));setText(fields["self_light"],std::to_string(base["self_light"].integer()));comboSet(fields["ao"],base["ao"].boolean(true)?1:0);
        setText(fields["block_tints"],base["block_tints"].isObject()?base["block_tints"].dump():"{}");setText(fields["item_tints"],base["item_tints"].isObject()?base["item_tints"].dump():"{}");
        auto biome=base["biome_tint"];comboSet(fields["biome"],biome.null()?0:biome["mode"].str()=="grass"?1:biome["mode"].str()=="foliage"?2:3);setText(fields["temperature"],displayNumber(biome["temperature"].number(.8)));setText(fields["downfall"],displayNumber(biome["downfall"].number(.4)));setText(fields["colormap"],biome["colormap"].str());setText(fields["water"],biome["water_color"].str("#3f76e4"));setText(fields["probe_pos"],(base["emission_sources"].isArray()&&base["emission_sources"].size()?base["emission_sources"][0]:J())["pos"].isArray()?(base["emission_sources"].isArray()&&base["emission_sources"].size()?base["emission_sources"][0]:J())["pos"].dump():"[1,1,0]");setText(fields["probe_level"],std::to_string((base["emission_sources"].isArray()&&base["emission_sources"].size()?base["emission_sources"][0]:J())["level"].integer()));
        for(auto& p:pages)p->loading=false;loading=false;touch();
    }
    J draft()const{
        auto value=base;value["subject"]=J::object({{"kind",std::array<const char*,4>{"document","model","blockstate","texture"}[comboIndex(fields.at("kind"))]},{"id",trim(stringEdit(fields.at("resource")))}});
        value["context"]=contexts[comboIndex(fields.at("context"))];value["state"]=J::parse(stringEdit(fields.at("state")));value["render_type"]=layers[comboIndex(fields.at("layer"))];value["arrangement"]=arrangements[comboIndex(fields.at("arrangement"))];
        value["mipmap_levels"]=comboIndex(fields.at("mips"));value["mip_level"]=comboIndex(fields.at("lod"))-1;value["time_ms"]=numberEdit(fields.at("time"),0,120000);value["sort_translucent"]=comboIndex(fields.at("sort"))==1;
        if(!value["camera"].isObject())value["camera"]=J::object();value["camera"]["distance"]=numberEdit(fields.at("distance"),1,4096);
        if(scene&&value["context"]==scene->options["context"]){value["camera"]["yaw"]=camera.yaw;value["camera"]["pitch"]=camera.pitch;value["camera"]["zoom"]=camera.zoom;}else if(scene){bool block=value["context"].str()=="block";value["camera"]["yaw"]=block?30:0;value["camera"]["pitch"]=block?25:0;value["camera"]["zoom"]=1;value["camera"]["projection"]=block?"perspective":"orthographic";}
        if(!value["environment"].isObject())value["environment"]=J::object();value["environment"]["sky_light"]=integerEdit(fields.at("sky"),0,15);value["environment"]["block_light"]=integerEdit(fields.at("block"),0,15);value["environment"]["gamma"]=numberEdit(fields.at("gamma"),0,1);
        value["self_light"]=integerEdit(fields.at("self_light"),0,15);value["ao"]=comboIndex(fields.at("ao"))==1;value["block_tints"]=J::parse(stringEdit(fields.at("block_tints")));value["item_tints"]=J::parse(stringEdit(fields.at("item_tints")));
        int biome=comboIndex(fields.at("biome"));if(biome){auto settings=base["biome_tint"].isObject()?base["biome_tint"]:J::object();settings["mode"]=std::array<const char*,3>{"grass","foliage","water"}[biome-1];settings["temperature"]=numberEdit(fields.at("temperature"),0,1);settings["downfall"]=numberEdit(fields.at("downfall"),0,1);auto source=trim(stringEdit(fields.at("colormap")));if(!source.empty())settings["colormap"]=source;else settings.obj().erase("colormap");settings["water_color"]=stringEdit(fields.at("water"));value["biome_tint"]=settings;}else value["biome_tint"]=J();
        int level=integerEdit(fields.at("probe_level"),0,15);value["emission_sources"]=base["emission_sources"].isArray()?base["emission_sources"]:J::array();if(level){J probe=J::object({{"pos",J::parse(stringEdit(fields.at("probe_pos")))},{"level",level}});if(value["emission_sources"].size())value["emission_sources"][0]=probe;else value["emission_sources"].arr().push_back(probe);}else if(value["emission_sources"].size())value["emission_sources"].arr().erase(value["emission_sources"].arr().begin());return value;
    }
    void updateDetails(const J& bundle){
        auto validation=bundle["validation"];std::string text=validation["passed"].boolean()?"资源解析通过\r\n":"资源存在错误\r\n";
        text+=std::to_string(bundle["faces"].size())+" 个面 · "+std::to_string(bundle["textures"].size())+" 张纹理\r\n"+std::to_string(bundle["catalog"]["cases"].size())+" 个声明状态 / 加权组合\r\n\r\n";
        text+="面像素密度（像素 / 方块）\r\n"+displayNumber(bundle["density_summary"]["min"].number())+" — "+displayNumber(bundle["density_summary"]["max"].number())+"\r\n\r\n";
        if(bundle["density"].isArray())for(auto& row:bundle["density"].arr())text+=row["face"].str()+" · "+fs::path(wide(row["texture"].str())).filename().string()+"\r\n"+(row["texels_per_block"][0].null()?"—":displayNumber(row["texels_per_block"][0].number()))+" × "+(row["texels_per_block"][1].null()?"—":displayNumber(row["texels_per_block"][1].number()))+"\r\n";
        text+="\r\n检查信息\r\n";if(validation["issues"].isArray())for(auto& row:validation["issues"].arr())text+=row["code"].str()+"\r\n"+row["message"].str()+"\r\n\r\n";
        text+="\r\n生效模型与来源\r\n"+mcui::pretty(bundle["selected_models"])+"\r\n";
        if(bundle["textures"].isArray())for(auto& texture:bundle["textures"].arr())text+=texture["id"].str()+"\r\n ← "+texture["source"].str()+"\r\n";
        setText(fields["report"],text);
    }
    void refresh(bool batch=false,int offset=0){
        auto value=draft();auto version=++serial;busy=true;dirty=false;sheet=Image();say(batch?L"正在生成状态与视图对照…":L"正在读取资源、解析模型并准备纹理…");
        J request=J::object({{"action",batch?"minecraft_preview":"minecraft_scene"},{"options",value}});if(batch){request["batch"]=true;request["case_offset"]=offset;request["case_limit"]=8;int contextSet=comboIndex(fields["batch_contexts"]);if(contextSet){request["contexts"]=J::array();for(int i=0;i<(contextSet==1?3:9);++i)request["contexts"].arr().push_back(contexts[i]);}}else request["include_pixels"]=true;
        auto weak=weak_from_this();app.rpc->call(request,[weak,version,batch,offset](const J& response){auto self=weak.lock();if(!self||self->done||version!=self->serial)return;self->safe([&]{self->busy=false;if(response.contains("error"))throw std::runtime_error(response["error"].str());if(!response["validation"]["passed"].boolean()){self->scene.reset();auto invalid=response["scene"];invalid["validation"]=response["validation"];self->updateDetails(invalid);self->say(L"所选资源尚无法解析，请查看右侧检查结果。");InvalidateRect(self->canvas,nullptr,FALSE);return;}
            if(batch){self->sheet=decodePreview(response["image"].str());self->report=response["report"];self->batchOffset=offset;self->nextOffset=response["report"]["next_case_offset"].null()?-1:response["report"]["next_case_offset"].integer();self->say(L"状态对照 · "+std::to_wstring(offset+1)+L"—"+std::to_wstring(offset+response["report"]["case_count"].integer())+L" / "+std::to_wstring(response["report"]["total_cases"].integer()));}
            else {auto next=std::make_unique<McScene>(response["scene"]);self->camera=next->camera;self->gpu->prepare(*next);self->report=response["scene"];self->scene=std::move(next);self->observed=self->app.tokens();self->updateDetails(response["scene"]);self->fillCatalog(response["scene"]["catalog"]["resources"]);self->say(L"预览已更新 · "+std::to_wstring(self->scene->faces.size())+L" 个面 · "+(self->gpu->available?L"GPU 实时渲染":L"CPU 渲染"));}
            self->arrange();InvalidateRect(self->canvas,nullptr,FALSE);
        });},true);
    }
    void fillCatalog(const J& rows){resources=rows;auto h=fields["catalog"];loading=true;SendMessageW(h,CB_RESETCONTENT,0,0);for(auto& row:rows.arr()){auto label=wide(row["kind"].str()+" · "+row["id"].str());SendMessageW(h,CB_ADDSTRING,0,LPARAM(label.c_str()));}int selected=0;for(int i=0;i<int(rows.size());++i)if(rows[i]==base["subject"])selected=i;comboSet(h,selected);loading=false;}
